const http = require('http');
const HOST = '127.0.0.1', PORT = 33069;
function req(method, path, {cookie, body} = {}) {
  return new Promise((resolve, reject) => {
    const data = body === undefined ? null : Buffer.from(JSON.stringify(body));
    const headers = {Host: '127.0.0.1:3000'};
    if (cookie) headers['Cookie'] = cookie;
    if (data) { headers['Content-Type'] = 'application/json'; headers['Content-Length'] = data.length; }
    const r = http.request({host: HOST, port: PORT, method, path, headers}, (res) => {
      let chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString();
        let json = null; try { json = JSON.parse(text); } catch {}
        resolve({status: res.statusCode, headers: res.headers, text, json});
      });
    });
    r.on('error', reject);
    if (data) r.write(data);
    r.end();
  });
}
async function login(username, password) {
  const r = await req('POST', '/app/login', {body: {username, password}});
  const sc = r.headers['set-cookie'];
  if (!sc) throw new Error('no cookie for ' + username + ': ' + r.status + ' ' + r.text);
  const cookie = sc.map(c => c.split(';')[0]).join('; ');
  return {cookie, loginResp: r};
}
function fmt(r) { return `${r.status} ${r.text.slice(0,300)}`; }
module.exports = {req, login, fmt};
EOF
