  ['private_reports', ['note','detail'], ['create','read','delete']],
  ['cached_reports', ['note','detail'], ['create','read','delete']],
  ['login_reports', ['note'], ['create','read','delete']],
  ['stale_reports', ['note'], ['create','read','update','delete']],
  ['forbidden_reports', ['note'], ['create','read','delete']],
  ['echo_reports', ['note'], ['create','read','delete']],
  ['expiring_reports', ['note'], ['create','read','delete']],
];
