  const bob = await login('bob','bob-password');
  const admin = await login('admin','admin-password');
  const tag = 'M' + Date.now().toString(36);
  for (const [cls, fields, ops] of CLASSES) {
    const mk = (who, extra) => Object.fromEntries(fields.map((f,i)=>[f, f==='detail' ? `${who}-${cls}-detail-${tag}` : `${who}-${cls}-note-${tag}${i?i:''}`]));
    const ca = await req('POST', `/app/api/${cls}`, {cookie: alice.cookie, body: mk('alice')});
    const cb = await req('POST', `/app/api/${cls}`, {cookie: bob.cookie, body: mk('bob')});
    const ida = ca.json && ca.json.id, idb = cb.json && cb.json.id;
    console.log(`\n=== ${cls} createA=${fmt(ca)} | createB=${fmt(cb)}`);
    if (!ida) continue;
    const show = async (label, r) => console.log(`  ${label}: ${fmt(r)}`);
    await show('alice->own', await req('GET', `/app/api/${cls}/${ida}`, {cookie: alice.cookie}));
    await show('bob->alice', await req('GET', `/app/api/${cls}/${ida}`, {cookie: bob.cookie}));
    await show('admin->alice', await req('GET', `/app/api/${cls}/${ida}`, {cookie: admin.cookie}));
    await show('anon->alice', await req('GET', `/app/api/${cls}/${ida}`));
    if (idb) await show('alice->bob', await req('GET', `/app/api/${cls}/${idb}`, {cookie: alice.cookie}));
    if (ops.includes('update')) {
      await show('bobPATCH->alice', await req('PATCH', `/app/api/${cls}/${ida}`, {cookie: bob.cookie, body: {note: `BOB-WROTE-${tag}`}}));
      await show('alice re-read', await req('GET', `/app/api/${cls}/${ida}`, {cookie: alice.cookie}));
    }
    if (ops.includes('delete')) {
      await show('bobDEL->alice', await req('DELETE', `/app/api/${cls}/${ida}`, {cookie: bob.cookie}));
      await show('alice re-read', await req('GET', `/app/api/${cls}/${ida}`, {cookie: alice.cookie}));
    }
    await show('aliceDEL->own', await req('DELETE', `/app/api/${cls}/${ida}`, {cookie: alice.cookie}));
  }
})().catch(e => { console.error(e); process.exit(1); });
